-- Core marketplace schema; this matches the tables already created in the connected project.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text not null default '',role text not null default 'customer' check(role in('customer','vendor','admin','delivery_boy')),is_active boolean not null default true,availability_status text not null default 'offline',latitude double precision,longitude double precision,last_location_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.vendors(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete set null,name text not null,slug text not null unique,description text not null default '',logo_url text not null default '',phone text not null default '',address text not null default '',status text not null default 'pending' check(status in('pending','approved','rejected','suspended')),latitude double precision,longitude double precision,created_at timestamptz not null default now(),constraint vendors_coordinates_paired check ((latitude is null)=(longitude is null)),constraint vendors_latitude_valid check(latitude is null or latitude between -90 and 90),constraint vendors_longitude_valid check(longitude is null or longitude between -180 and 180));
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,image_url text not null default '',sort_order int not null default 0,is_active boolean not null default true,parent_id uuid null references public.categories(id) on delete set null,created_at timestamptz not null default now(),constraint categories_not_own_parent check(parent_id is null or parent_id<>id));
create index if not exists categories_parent_sort_idx on public.categories(parent_id,sort_order,name);
create table if not exists public.products(id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.vendors(id) on delete restrict,category_id uuid references public.categories(id) on delete set null,name text not null,slug text not null unique,description text not null default '',price numeric(12,2) not null check(price>=0),compare_at_price numeric(12,2) check(compare_at_price is null or compare_at_price>=price),sku text not null default '',image_url text not null default '',image_public_id text not null default '',sizes text[] not null default '{}',colors text[] not null default '{}',stock_quantity int not null default 0 check(stock_quantity>=0),is_active boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.customer_addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,recipient_name text not null,phone text not null,line1 text not null,line2 text not null default '',landmark text not null default '',city text not null default 'Rayachoty',state text not null default 'Andhra Pradesh',postal_code text not null default '',is_default boolean not null default false,created_at timestamptz not null default now(),latitude double precision,longitude double precision,notes text not null default '',updated_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique,customer_id uuid not null references auth.users(id) on delete restrict,vendor_id uuid not null references public.vendors(id) on delete restrict,status text not null default 'placed' check(status in('placed','confirmed','packed','out_for_delivery','delivered','cancelled')),assigned_delivery_boy_id uuid references auth.users(id) on delete set null,payment_method text not null default 'cod' check(payment_method='cod'),payment_status text not null default 'pending' check(payment_status in('pending','paid','refunded')),subtotal numeric(12,2) not null check(subtotal>=0),delivery_fee numeric(12,2) not null default 0 check(delivery_fee>=0),total numeric(12,2) not null check(total>=0),address_snapshot jsonb not null,notes text not null default '',vendor_name_snapshot text not null default '',vendor_phone_snapshot text not null default '',vendor_address_snapshot text not null default '',vendor_latitude_snapshot double precision,vendor_longitude_snapshot double precision,delivery_otp_hash text,delivery_otp_expires_at timestamptz,delivery_otp_sent_at timestamptz,delivery_otp_attempts integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.order_address_audit(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,changed_by uuid not null references auth.users(id) on delete restrict,correction_reason text not null,previous_address jsonb not null,corrected_address jsonb not null,created_at timestamptz not null default now());
create table if not exists public.account_notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references auth.users(id) on delete cascade,event_type text not null,title text not null,body text not null,order_id uuid not null references public.orders(id) on delete cascade,created_at timestamptz not null default now(),read_at timestamptz,unique(recipient_id,order_id,event_type));
create table if not exists public.delivery_assignment_notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references auth.users(id) on delete cascade,order_id uuid not null references public.orders(id) on delete cascade,order_number text not null,message text not null,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,image_url text not null default '',size text not null default '',color text not null default '',quantity int not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0),line_total numeric(12,2) not null check(line_total>=0));
create index if not exists products_active_category_idx on public.products(is_active,category_id);
create index if not exists products_vendor_idx on public.products(vendor_id);
create index if not exists products_category_idx on public.products(category_id);
create index if not exists vendors_owner_idx on public.vendors(owner_id);
create index if not exists orders_customer_created_idx on public.orders(customer_id,created_at desc);
create index if not exists orders_vendor_created_idx on public.orders(vendor_id,created_at desc);
create index if not exists orders_delivery_assignment_idx on public.orders(assigned_delivery_boy_id,status,created_at desc);
create index if not exists order_items_order_idx on public.order_items(order_id);
create index if not exists order_items_product_idx on public.order_items(product_id);
create index if not exists addresses_user_idx on public.customer_addresses(user_id);
create unique index if not exists customer_addresses_one_default_per_user on public.customer_addresses(user_id) where is_default=true;
create index if not exists account_notifications_recipient_created_idx on public.account_notifications(recipient_id,created_at desc);
create index if not exists account_notifications_unread_idx on public.account_notifications(recipient_id) where read_at is null;
create index if not exists delivery_assignment_notifications_recipient_idx on public.delivery_assignment_notifications(recipient_id,created_at desc);
alter table public.profiles enable row level security;
alter table public.vendors enable row level security;
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.customer_addresses enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.account_notifications enable row level security;
alter table public.delivery_assignment_notifications enable row level security;
alter table public.order_address_audit enable row level security;
grant select on public.vendors,public.categories,public.products to anon,authenticated;
grant select,insert,update on public.profiles to authenticated;
grant select,insert,update,delete on public.customer_addresses to authenticated;
grant select on public.orders,public.order_items to authenticated;
revoke all on public.order_address_audit from anon,authenticated;
revoke all on public.account_notifications from anon,authenticated;
revoke all on public.delivery_assignment_notifications from anon,authenticated;
drop policy if exists "Public can view approved vendors" on public.vendors;
create policy "Public can view approved vendors" on public.vendors for select to anon,authenticated using(status='approved');
drop policy if exists "Public can view active categories" on public.categories;
create policy "Public can view active categories" on public.categories for select to anon,authenticated using(is_active=true);
drop policy if exists "Public can view active products from approved vendors" on public.products;
create policy "Public can view active products from approved vendors" on public.products for select to anon,authenticated using(is_active=true and exists(select 1 from public.vendors v where v.id=vendor_id and v.status='approved'));
drop policy if exists "Users can view own profile" on public.profiles;
create policy "Users can view own profile" on public.profiles for select to authenticated using((select auth.uid())=id);
drop policy if exists "Users can create own profile" on public.profiles;
create policy "Users can create own profile" on public.profiles for insert to authenticated with check((select auth.uid())=id);
drop policy if exists "Users can update own profile" on public.profiles;
create policy "Users can update own profile" on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
drop policy if exists "Users manage own addresses" on public.customer_addresses;
create policy "Users manage own addresses" on public.customer_addresses for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users can view own orders" on public.orders;
create policy "Users can view own orders" on public.orders for select to authenticated using((select auth.uid())=customer_id);
drop policy if exists "Users can view own order items" on public.order_items;
create policy "Users can view own order items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=(select auth.uid())));
insert into public.categories(name,slug,sort_order) values('Women','women',1),('Men','men',2),('Kids','kids',3),('Ethnic Wear','ethnic-wear',4),('Accessories','accessories',5) on conflict(slug) do nothing;
